import{a5 as n,ap as s,am as e,ax as i,cS as d,aw as r,av as o,bY as l,bH as c}from"./index-Czgq_Cxz.js";const u={},b={class:"lesson"},f={class:"lesson-nav","aria-label":"Kursnavigation"};function v(g,a){const t=l("router-link");return c(),s("main",b,[e("nav",f,[i(t,{to:{name:"3tgg12"}},{default:d(()=>[...a[0]||(a[0]=[r("← Zur Übersicht 3TGG12",-1)])]),_:1})]),a[1]||(a[1]=o('<section class="slide title-slide" aria-labelledby="lesson-title" data-v-dab53f73><p class="eyebrow" data-v-dab53f73>GRUNDLAGEN</p><h1 id="lesson-title" data-v-dab53f73>VISUELLE<br data-v-dab53f73>KOMMUNIKATION</h1><footer data-v-dab53f73>CHS | Heckel</footer></section><section class="slide" aria-labelledby="definition-title" data-v-dab53f73><header class="subject" data-v-dab53f73><span data-v-dab53f73>GESTALTUNGS UND MEDIENTECHNIK</span><span data-v-dab53f73>Eingangsklasse</span></header><h2 id="definition-title" class="question" data-v-dab53f73>Was versteht man unter <strong data-v-dab53f73>visueller Kommunikation?</strong></h2><div class="definition-copy" data-v-dab53f73><p data-v-dab53f73><strong data-v-dab53f73>Visuelle Kommunikation</strong> ist die <strong data-v-dab53f73>Übermittlung von Informationen</strong> über <strong data-v-dab53f73>visuelle Zeichen</strong> - also über <strong data-v-dab53f73>Bilder, Symbole, Zeichen, Formen</strong> und <strong data-v-dab53f73>Gestaltung.</strong></p><p data-v-dab53f73><strong data-v-dab53f73>Zeichen</strong> in der <strong data-v-dab53f73>Kommunikations- und Zeichentheorie</strong> = alles, was auf etwas anderes verweist und Bedeutung trägt.</p></div><footer data-v-dab53f73>CHS | Heckel</footer></section><section class="slide" aria-labelledby="task-title" data-v-dab53f73><header class="subject" data-v-dab53f73><span data-v-dab53f73>GESTALTUNGS UND MEDIENTECHNIK</span><span data-v-dab53f73>Eingangsklasse</span></header><h2 id="task-title" data-v-dab53f73>Aufgabe</h2><p data-v-dab53f73>Zeichne vier Quadrate in deine Kladde (7 x 7 cm). Verwende in jedem Quadrat nur einen Punkt und einen Strich. Ordne Punkt und Strich jeweils so an, dass vier unterschiedliche kleine Geschichten entstehen. <strong data-v-dab53f73>(Bearbeitungszeit 45 Min.)</strong></p><p data-v-dab53f73>Anschließend stellt jede Person ihre vier Geschichten kurz vor.<br data-v-dab53f73><strong data-v-dab53f73>( Präsentationszeit etwa 3 Min. pro Person)</strong></p><p data-v-dab53f73>→ Ziel ist es zu erkennen, dass allein durch die Position der Grundelemente Punkt und Linie sehr viel Bedeutung transportiert werden kann.</p><footer data-v-dab53f73>CHS | Heckel</footer></section>',3)),a[2]||(a[2]=e("section",{class:"slide sketch-slide","aria-label":"Beispiele im DIN-A5-Skizzenbuch"},[e("header",{class:"subject"},[e("span",null,"GESTALTUNGS UND MEDIENTECHNIK"),e("span",null,"Eingangsklasse")]),e("div",{class:"book-surround"},[e("div",{class:"sketchbook",role:"group","aria-label":"Aufgeschlagenes DIN-A5-Skizzenbuch mit zwei Hochformatseiten"},[e("h2",null,"#1 Visuelle Kommunikation mit Punkt und Linie"),e("div",{class:"book-page left-page"},[e("figure",null,[e("svg",{viewBox:"0 0 200 200",role:"img","aria-label":"Ein Punkt schwebt über einer waagerechten Linie"},[e("circle",{cx:"100",cy:"92",r:"15"}),e("path",{d:"M66 130 H132",stroke:"currentColor","stroke-width":"9"})]),e("figcaption",null,"Punkt schwebt auf Linie")]),e("div",{class:"empty-square","aria-label":"Freies Quadrat für eine weitere Geschichte"})]),e("div",{class:"book-page right-page"},[e("figure",null,[e("svg",{viewBox:"0 0 200 200",role:"img","aria-label":"Eine schräge Linie steht auf einem Punkt und kippt nach rechts"},[e("circle",{cx:"96",cy:"130",r:"15"}),e("path",{d:"M97 113 L132 56",stroke:"currentColor","stroke-width":"9"})]),e("figcaption",null,"Linie steht auf Punkt und kippt um")]),e("div",{class:"empty-square","aria-label":"Freies Quadrat für eine weitere Geschichte"})])])]),e("footer",null,"CHS | Heckel")],-1))])}const p=n(u,[["render",v],["__scopeId","data-v-dab53f73"]]);exp